source.declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    GuardClosed : BOOL;
END_VAR
VAR_OUTPUT
    Run : BOOL;
END_VAR

source.implementation:
IF Stop OR NOT GuardClosed THEN
    Run := FALSE;
ELSIF Start THEN
    Run := TRUE;
END_IF

